	greater := n - x

	// simulate binary search
	left, right := 0, n
	var cntLess, cntGreater int64
	for left < right {
		mid := (left + right) / 2
		if mid <= pos {
			if mid == pos {
				left = mid + 1
			} else {
				// need a value < x
				cntLess++
				left = mid + 1
			}
