	in := bufio.NewReader(os.Stdin)
	var n, x, pos int
	fmt.Fscan(in, &n, &x, &pos)

	less := x - 1          // numbers < x
	greater := n - x       // numbers > x
	var cntLess, cntGreater int64

	l, r := 0, n
	for l < r {
		mid := (l + r) / 2
		if mid <= pos {
			if mid < pos {
				// must be < x
				cntLess++
				less--
			}
			l = mid + 1
		} else {
			// mid > pos, must be > x
			cntGreater++
			greater--
			r = mid
		}
	}

	if less < 0 || greater < 0 {
		fmt.Println(0)
		return
	}

	ans := int64(1)

	// ways to choose and arrange required smaller numbers
	for i := int64(0); i < cntLess; i++ {
		ans = ans * int64(less) % MOD
		less--
	}

	// ways to choose and arrange required greater numbers
	for i := int64(0); i < cntGreater; i++ {
		ans = ans * int64(greater) % MOD
		greater--
	}

	// remaining positions can be filled with remaining numbers in any order
	remaining := n - 1 - int(cntLess+cntGreater)
	for i := 1; i <= remaining; i++ {
		ans = ans * int64(i) % MOD
	}

	fmt.Println(ans)
}
